<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {request} from './service';
const data=ref<any>({items:[],recent:[],version:1}),query=ref(''),selected=ref<any>(null),editing=ref(false),draft=ref<any[]>([]),busy=ref(false),notice=ref(''),frameLoaded=ref(false);
const rows=computed(()=>data.value.items.filter(row=>(row.title+' '+row.tags+' '+row.description).toLowerCase().includes(query.value.toLowerCase())));
async function load(){data.value=await request('/api/private/reference-docs');}
async function visit(row){selected.value=row;frameLoaded.value=false;await request('/api/private/reference-docs/visit','POST',{id:row.id});await load();}
function edit(){draft.value=data.value.items.map(({embeddable,...item})=>({...item}));editing.value=true;}
function add(){draft.value.push({id:crypto.randomUUID(),title:'',url:'https://',tags:'',description:'',public:false});}
async function save(){busy.value=true;try{data.value=await request('/api/private/reference-docs','PUT',{version:data.value.version,items:draft.value});editing.value=false;selected.value=null;notice.value='文档书架已保存。';}catch(e){notice.value=e.message;}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>notice.value=e.message));
</script>
<template><section class="reference-page"><header><div><span class="space-eyebrow">DEVELOPER REFERENCE / A SMALL BOOKSHELF</span><h1>随手查阅的开发书架。</h1><p>收藏常用文档；允许嵌入的站点在这里阅读，其余保留可靠的外链。</p></div><el-button @click="edit">整理书架</el-button></header><p v-if="notice" role="status">{{notice}}</p><section v-if="editing" class="reference-edit"><h2>书架设置</h2><form @submit.prevent="save"><article v-for="(item,i) in draft" :key="item.id"><el-input v-model="item.title" placeholder="名称" aria-label="文档名称" maxlength="100"/><el-input v-model="item.url" placeholder="HTTPS 文档地址" aria-label="文档地址"/><el-input v-model="item.tags" placeholder="标签（逗号分隔）" aria-label="文档标签"/><el-checkbox v-model="item.public">允许首页公开</el-checkbox><el-button type="danger" plain @click="draft.splice(i,1)">移除</el-button></article><div><el-button @click="add">添加书签</el-button><el-button type="primary" native-type="submit" :loading="busy">保存书架</el-button><el-button @click="editing=false">取消</el-button></div></form></section><div class="reference-tools"><el-input v-model="query" clearable placeholder="搜索名称、标签或说明" aria-label="搜索开发文档"/><small>最近访问：{{data.recent.map(id=>data.items.find(row=>row.id===id)?.title).filter(Boolean).slice(0,3).join('、')||'暂无'}}</small></div><div class="reference-grid"><article v-for="row in rows" :key="row.id"><div><small>{{row.tags}}</small><h2>{{row.title}}</h2><p>{{row.description}}</p></div><footer><el-button size="small" :disabled="!row.embeddable" @click="visit(row)">{{row.embeddable?'站内阅读':'源站限制内嵌'}}</el-button><a :href="row.url" target="_blank" rel="noopener noreferrer" @click="visit(row)">新标签页 ↗</a></footer></article></div><section v-if="selected?.embeddable" class="reference-reader"><header><div><h2>{{selected.title}}</h2><p>外站内容由来源网站直接提供；若空白或被源站阻止，请使用右侧外链。</p></div><a :href="selected.url" target="_blank" rel="noopener noreferrer">新标签页 ↗</a><el-button @click="selected=null">关闭</el-button></header><p v-if="!frameLoaded" role="status">正在加载外站文档…</p><iframe :key="selected.id" :src="selected.url" :title="selected.title" sandbox="allow-scripts allow-same-origin allow-popups" referrerpolicy="no-referrer" loading="lazy" @load="frameLoaded=true"/></section></section></template>
<style scoped>
.reference-page{max-width:1320px;margin:auto}.reference-page>header,.reference-reader>header{display:flex;justify-content:space-between;align-items:center;gap:15px}.reference-page h1{font-size:29px;margin:12px 0}.reference-page p{font-size:12px;color:var(--studio-muted);line-height:1.8}.reference-tools{display:flex;align-items:center;gap:20px;margin:28px 0 20px}.reference-tools .el-input{max-width:400px}.reference-tools small{font-size:11px;color:var(--studio-muted)}.reference-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.reference-grid>article{border:1px solid var(--studio-line);border-radius:10px;background:var(--studio-panel);padding:23px;display:flex;flex-direction:column;justify-content:space-between}.reference-grid small{font-size:10px;color:var(--studio-muted)}.reference-grid h2{font-size:18px;margin:12px 0}.reference-grid footer{display:flex;gap:12px;align-items:center;margin-top:18px;flex-wrap:wrap}.reference-grid a,.reference-reader a{font-size:12px}.reference-reader{margin-top:28px;border-top:1px solid var(--studio-line);padding-top:15px}.reference-reader h2{font-size:19px}.reference-reader iframe{width:100%;height:74vh;min-height:500px;border:1px solid var(--studio-line);margin-top:14px;border-radius:7px;background:#fff}.reference-edit{padding:20px;background:var(--studio-panel);border:1px solid var(--studio-line);margin-top:20px;border-radius:8px}.reference-edit h2{font-size:18px}.reference-edit article{display:grid;grid-template-columns:1fr 2fr 1fr auto auto;gap:10px;margin:12px 0}.reference-edit form>div{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}@media(max-width:900px){.reference-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.reference-edit article{grid-template-columns:1fr}}@media(max-width:600px){.reference-grid{grid-template-columns:1fr}.reference-page>header,.reference-reader>header,.reference-tools{align-items:flex-start;flex-wrap:wrap}.reference-page h1{font-size:25px}.reference-reader iframe{min-height:400px}}
</style>
